export interface Row {
  id: number;
  name: string;
  category: string;
  score: number;
}

/** One entry per sort column; later entries break ties of earlier ones. */
export interface SortSpec {
  id: string;
  desc: boolean;
}

export interface TableState {
  rows: Row[];
  sortBy: SortSpec[];
  /** Matched case-insensitively as a substring against every string column. */
  globalFilter: string;
  pageIndex: number;
  pageSize: number;
}

export type TableAction =
  | { type: 'TOGGLE_SORT'; id: string; shift?: boolean }
  | { type: 'SET_FILTER'; value: string }
  | { type: 'SET_PAGE'; index: number }
  | { type: 'SET_PAGE_SIZE'; size: number };

export function createInitialState(rows: Row[], pageSize = 10): TableState {
  return { rows, sortBy: [], globalFilter: '', pageIndex: 0, pageSize };
}

/* ------------------------------------------------------------------ */
/* Selectors                                                           */
/* ------------------------------------------------------------------ */

function matchesFilter(row: Row, needle: string): boolean {
  if (needle === '') return true;
  for (const value of Object.values(row)) {
    if (typeof value === 'string' && value.toLowerCase().includes(needle)) {
      return true;
    }
  }
  return false;
}

function compareValues(a: unknown, b: unknown): number {
  if (typeof a === 'number' && typeof b === 'number') return a - b;
  const sa = String(a ?? '');
  const sb = String(b ?? '');
  return sa < sb ? -1 : sa > sb ? 1 : 0;
}

/**
 * Filter -> stable sort -> slice. The decorate-with-index step guarantees
 * stability even on engines whose Array#sort is not guaranteed stable.
 */
export function selectVisibleRows(state: TableState): Row[] {
  const needle = state.globalFilter.toLowerCase();
  const filtered = state.rows.filter((row) => matchesFilter(row, needle));

  if (state.sortBy.length === 0) {
    const start = state.pageIndex * state.pageSize;
    return filtered.slice(start, start + state.pageSize);
  }

  const decorated = filtered.map((row, i) => ({ row, i }));
  decorated.sort((a, b) => {
    for (const { id, desc } of state.sortBy) {
      const cmp = compareValues(a.row[id], b.row[id]);
      if (cmp !== 0) return desc ? -cmp : cmp;
    }
    return a.i - b.i; // stable tiebreak: original row order
  });

  const start = state.pageIndex * state.pageSize;
  return decorated.slice(start, start + state.pageSize).map((d) => d.row);
}

/** Number of pages for the currently filtered/sorted data (never < 1). */
export function selectPageCount(state: TableState, pageSize = state.pageSize): number {
  const needle = state.globalFilter.toLowerCase();
  const count = state.rows.reduce(
    (n, row) => n + (matchesFilter(row, needle) ? 1 : 0),
    0,
  );
  return Math.max(1, Math.ceil(count / Math.max(1, pageSize)));
}

/* ------------------------------------------------------------------ */
/* Reducer                                                             */
/* ------------------------------------------------------------------ */

export function tableReducer(state: TableState, action: TableAction): TableState {
  switch (action.type) {
    case 'TOGGLE_SORT': {
      const { id, shift = false } = action;
      const idx = state.sortBy.findIndex((s) => s.id === id);

      if (!shift) {
        // Without shift the sort is replaced wholesale.
        // Cycle for a lone existing column: asc -> desc -> off.
        if (idx !== -1 && state.sortBy.length === 1) {
          return {
            ...state,
            sortBy: state.sortBy[0].desc ? [] : [{ id, desc: true }],
          };
        }
        return { ...state, sortBy: [{ id, desc: false }] };
      }

      // Shift appends to (or cycles within) the multi-column sort.
      if (idx === -1) {
        return { ...state, sortBy: [...state.sortBy, { id, desc: false }] };
      }
      if (idx === state.sortBy.length - 1) {
        // Trailing column cycles asc -> desc -> removed.
        if (!state.sortBy[idx].desc) {
          const sortBy = state.sortBy.slice();
          sortBy[idx] = { id, desc: true };
          return { ...state, sortBy };
        }
        return { ...state, sortBy: state.sortBy.slice(0, idx) };
      }
      // Column in the middle of the chain: just flip its direction.
      const sortBy = state.sortBy.slice();
      sortBy[idx] = { id, desc: !state.sortBy[idx].desc };
      return { ...state, sortBy };
    }

    case 'SET_FILTER':
      // A new filter changes which rows exist, so pagination restarts.
      return { ...state, globalFilter: action.value, pageIndex: 0 };

    case 'SET_PAGE': {
      const maxPage = selectPageCount(state) - 1;
      const index = Math.min(Math.max(0, Math.floor(action.index)), maxPage);
      if (index === state.pageIndex) return state;
      return { ...state, pageIndex: index };
    }

    case 'SET_PAGE_SIZE': {
      const size = Math.max(1, Math.floor(action.size));
      // Keep the first currently-visible row visible:
      // it sits at absolute index pageIndex * oldPageSize within the
      // filtered+sorted list, so recompute the page that contains it.
      const topRow = state.pageIndex * state.pageSize;
      const maxPage = selectPageCount(state, size) - 1;
      const pageIndex = Math.min(Math.floor(topRow / size), maxPage);
      if (size === state.pageSize && pageIndex === state.pageIndex) return state;
      return { ...state, pageSize: size, pageIndex };
    }
  }
}
