  const tied: Row[] = [
    { id: 3, name: 'c', category: 'X', score: 5 },
    { id: 1, name: 'a', category: 'X', score: 5 },
    { id: 2, name: 'b', category: 'X', score: 5 },
    { id: 4, name: 'd', category: 'X', score: 1 },
  ];

  it('preserves original row order among equal keys', () => {
    const asc = selectVisibleRows(
      makeState({ rows: tied, sortBy: [{ id: 'score', desc: false }], pageSize: 10 }),
    );
    expect(asc.map((r) => r.id)).toEqual([4, 3, 1, 2]);

    const desc = selectVisibleRows(
      makeState({ rows: tied, sortBy: [{ id: 'score', desc: true }], pageSize: 10 }),
    );
    // Reversing the comparator reverses equal-key groups as one block, not pairwise.
    expect(desc.map((r) => r.id)).toEqual([2, 1, 3, 4]);
  });

