function deepFreeze<T>(obj: T): T {
  for (const v of Object.values(obj as object)) {
    if (v && typeof v === 'object') deepFreeze(v);
  }
  return Object.freeze(obj);
}

function invariantsHold(before: TableState, after: TableState): void {
  const count = refVisible({ ...after, pageIndex: 0, pageSize: Infinity }).length;
  const maxPage = Math.max(0, Math.ceil(count / after.pageSize) - 1);
  expect(after.pageIndex).toBeGreaterThanOrEqual(0);
  expect(after.pageIndex).toBeLessThanOrEqual(maxPage);
}

describe('exhaustive sweeps', () => {
  it('every (pageSize, pageIndex) pair serves the reference slice exactly', () => {
    for (const pageSize of [1, 2, 3, 7, 10, 56, 57, 58]) {
      for (
        let p = 0;
        p < selectPageCount(makeState({ pageSize }), pageSize);
        p++
      ) {
        const state = tableReducer(makeState({ pageSize }), { type: 'SET_PAGE', index: p });
        expect(state.pageIndex).toBe(p);
        const got = selectVisibleRows(state).map((r) => r.id);
        const want = refVisible(state);
        expect(got).toEqual(want);
        expect(got.length).toBeLessThanOrEqual(pageSize);
      }
    }
  });

  it('every page size transition keeps the previous top row visible', () => {
    const sizes = [1, 2, 3, 4, 5, 8, 10, 20, 25, 50, 57, 100];
    for (const oldSize of sizes) {
      for (const newSize of sizes) {
        for (const filter of ['', 'a', 'beta']) {
          const base = makeState({ pageSize: oldSize, globalFilter: filter });
          const total = refVisible({ ...base, pageIndex: 0, pageSize: Infinity }).length;
          const maxPage = Math.max(0, Math.ceil(total / oldSize) - 1);
          for (let p = 0; p <= maxPage; p++) {
            const before = tableReducer(base, { type: 'SET_PAGE', index: p });
            const topRowId = selectVisibleRows(before)[0]?.id;
            const after = tableReducer(before, { type: 'SET_PAGE_SIZE', size: newSize });
            invariantsHold(before, after);
            const visibleAfter = selectVisibleRows(after).map((r) => r.id);
            expect(visibleAfter).toContain(topRowId);
            // And it must be the very first row unless the list shrank above it.
            const fullAfter = refVisible({ ...after, pageIndex: 0, pageSize: Infinity });
            const absTop = after.pageIndex * after.pageSize;
            if (absTop < fullAfter.length) {
              expect(visibleAfter[0]).toBe(fullAfter[absTop]);
            }
          }
        }
      }
    }
  });

  it('randomized action fuzz: invariants hold and state stays pure', () => {
    // Deterministic PRNG (mulberry32) so failures reproduce.
    let seed = 0xc0ffee;
    const rand = () => {
      seed |= 0;
      seed = (seed + 0x6d2b79f5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
    const pick = <T,>(arr: readonly T[]): T => arr[Math.floor(rand() * arr.length)];

    // Frozen fixture: any mutation inside the reducer throws in strict mode.
    const frozenRows = deepFreeze(ROWS.map((r) => ({ ...r })));
    let state: TableState = deepFreeze(createInitialState(frozenRows, 10));

    const actions = [
      () => ({ type: 'TOGGLE_SORT' as const, id: pick(['score', 'name', 'category']), shift: rand() < 0.5 }),
      () => ({ type: 'SET_FILTER' as const, value: pick(['', 'a', 'BETA', 'row-1', 'zzz-nope']) }),
      () => ({ type: 'SET_PAGE' as const, index: Math.floor(rand() * 12) - 2 }),
      () => ({ type: 'SET_PAGE_SIZE' as const, size: pick([1, 3, 5, 10, 20, 60]) }),
    ];

    for (let step = 0; step < 3000; step++) {
      const action = pick(actions)();
      const snapshot = JSON.stringify(state);
      state = tableReducer(state, action);

      // Purity: input was not mutated (frozen would have thrown already).
      expect(JSON.stringify(state)).not.toBe(snapshot || null);

      // Structural invariants.
      const full = refVisible({ ...state, pageIndex: 0, pageSize: Infinity });
      const expectedPage = Math.min(
        state.pageIndex,
        Math.max(0, Math.ceil(full.length / state.pageSize) - 1),
      );
      expect(state.pageIndex).toBe(expectedPage);
      expect(state.pageSize).toBeGreaterThanOrEqual(1);

      const got = selectVisibleRows(state).map((r) => r.id);
      const start = state.pageIndex * state.pageSize;
      expect(got).toEqual(full.slice(start, start + state.pageSize));

      // Filter really applied to every visible row's string columns.
      if (state.globalFilter !== '') {
        const needle = state.globalFilter.toLowerCase();
        for (const row of selectVisibleRows(state)) {
          const hit =
            row.name.toLowerCase().includes(needle) ||
            row.category.toLowerCase().includes(needle);
          expect(hit).toBe(true);
        }
      }

      state = JSON.parse(JSON.stringify(state)); // unfreeze for next round
    }
  });
});
